</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <algorithm>
#include <iostream>
#include <cstdio>
#include <vector>
#include <deque>
using namespace std;

vector<int> e[2020];
int ir[20][20];
int sc[20][20];
int pc[20][20];
char s[20][20];
char p[20][20];
int dd[20][20];
const int dx[4] = {0, 1, -1, 0};
const int dy[4] = {1, 0, 0, -1};
vector<int> ns[20][20], np[20][20];

void add_edge(int a, int b) {
    e[a].push_back(b);
    e[b].push_back(a);
}

int dist_to_sink[2020];
int partner[2020];
int source_count, sink_count;

bool bfs() {
    deque<int> q;
    for (int i = 1; i <= source_count; ++i) {
        if (partner[i] == 0) {
            dist_to_sink[i] = 0;
            q.push_back(i);
        } else {
            dist_to_sink[i] = 3010;
        }
    }
    dist_to_sink[0] = 3010;
    while (!q.empty()) {
        int u = q.front();
        q.pop_front();
        if (dist_to_sink[u] < dist_to_sink[0]) {
            for (int i = 0; i < (int)e[u].size(); ++i) {
                int v = partner[e[u][i]];
                if (dist_to_sink[v] > dist_to_sink[u] + 1) {
                    dist_to_sink[v] = dist_to_sink[u] + 1;
                    q.push_back(v);
                }
            }
        }
    }
    return dist_to_sink[0] != 3010;
}

bool dfs(int x) {
    if (x == 0) return true;
    for (int i = 0; i < (int)e[x].size(); ++i) {
        int u = partner[e[x][i]];
        if (dist_to_sink[u] == dist_to_sink[x] + 1) {
            if (dfs(u)) {
                partner[x] = e[x][i];
                partner[e[x][i]] = x;
                return true;
            }
        }
    }
    return false;
}

int hopcroft_karp() {
    int ans = 0;
    while (bfs()) {
        for (int i = 1; i <= source_count; ++i) {
            if (partner[i] == 0) {
                ans += dfs(i);
            }
        }
    }
    return ans;
}

int n, t;

void work(int a, int b) {
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            dd[i][j] = 100000;
        }
    }
    deque<pair<int, int> > q;
    dd[a][b] = 0;
    q.push_back(make_pair(a, b));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop_front();
        for (size_t i = 0; i < np[x][y].size(); ++i) {
            for (size_t j = 0; j < ns[a][b].size(); ++j) {
                add_edge(ns[a][b][j], np[x][y][i]);
            }
        }
        if (dd[x][y] == ir[x][y]) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (sc[nx][ny] != -1 && dd[nx][ny] > dd[x][y] + 1 && dd[x][y] + 1 <= ir[nx][ny]) {
                dd[nx][ny] = dd[x][y] + 1;
                q.push_back(make_pair(nx, ny));
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            ir[i][j] = t;
    for (int i = 1; i <= n; ++i)
        scanf("%s", s[i] + 1);
    for (int i = 1; i <= n; ++i)
        scanf("%s", p[i] + 1);
    int rx, ry;
    source_count = 1, sink_count = 1000;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s[i][j] == 'Z' || s[i][j] == 'Y')
                sc[i][j] = -1, ir[i][j] = 0;
            if (s[i][j] == 'Z')
                rx = i, ry = j, ir[i][j] = 0;
            if ('0' <= s[i][j] && s[i][j] <= '9')
                sc[i][j] = s[i][j] - '0';
            for (int k = 0; k < sc[i][j]; ++k)
                ns[i][j].push_back(source_count++);
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if ('0' <= p[i][j] && p[i][j] <= '9')
                pc[i][j] = p[i][j] - '0';
            for (int k = 0; k < pc[i][j]; ++k)
                np[i][j].push_back(sink_count++);
        }
    }
    deque<pair<int, int> > q;
    q.push_back(make_pair(rx, ry));
    while (!q.empty()) {
        rx = q.front().first, ry = q.front().second;
        q.pop_front();
        int nx, ny;
        for (int d = 0; d < 4; ++d) {
            nx = rx + dx[d];
            ny = ry + dy[d];
            if (ir[nx][ny] > ir[rx][ry] + 1 && sc[nx][ny] != -1) {
                ir[nx][ny] = ir[rx][ry] + 1;
                q.push_back(make_pair(nx, ny));
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sc[i][j] > 0) {
                work(i, j);
            }
        }
    }
    printf("%d", hopcroft_karp());
    return 0;
}
